import { NextResponse } from "next/server";
import { readRepair, readRepairArtifact, repairPatchName } from "@/lib/repair/storage";
import { failureFrom } from "@/lib/http/api-response";

/**
 * `GET /api/repairs/:id/patch?attempt=1` — the model's diff, verbatim, as a `.patch` file.
 *
 * Only an attempt that the stored record actually names can be downloaded, and the file
 * name is generated by the engine, never accepted from the caller. The response is plain
 * text: a developer reads it, reviews it against the verification record, and applies it
 * themselves — nothing here merges, commits or approves anything.
 */
export async function GET(request: Request, context: { params: Promise<{ id: string }> }) {
  const { id } = await context.params;
  try {
    const repair = await readRepair(id);
    if (!repair) {
      return NextResponse.json(
        { error: { code: "repair_not_found", message: `No stored repair with id ${id}.` } },
        { status: 404 },
      );
    }

    const attemptParam = Number.parseInt(new URL(request.url).searchParams.get("attempt") ?? "1", 10);
    const attempt = repair.attempts.find((entry) => entry.attempt === attemptParam);
    if (!attempt || !attempt.patchArtifact) {
      return NextResponse.json(
        { error: { code: "repair_not_found", message: `Attempt ${attemptParam} has no stored patch.` } },
        { status: 404 },
      );
    }

    const name = repairPatchName(attempt.attempt);
    const patch = await readRepairArtifact(id, name);
    return new NextResponse(new Uint8Array(patch), {
      headers: {
        "content-type": "text/x-diff; charset=utf-8",
        "content-disposition": `attachment; filename="uiproof-${id}-attempt-${attempt.attempt}.patch"`,
        "cache-control": "no-store",
      },
    });
  } catch (error) {
    return failureFrom(error);
  }
}
